#!/usr/bin/env python3
"""Regenerate INDEX.md from the fixtures on disk.

The index is derived, never hand-maintained: the purpose column is each file's
own leading comment or docstring, so a fixture cannot drift from its entry.

    python3 tests/fixtures/make-index.py

PROVENANCE maps a fixture back to where it was retrieved from. Every file in
this collection was a scratch script under /tmp during the work; the column
exists so a reader can tell an original from a renamed copy, and so the naming
in the technique document can be traced back.
"""

import pathlib
import sys

HERE = pathlib.Path(__file__).resolve().parent

PROVENANCE = {
    "build/asan-build.sh": "/tmp/irctui-menu/g4/asan_build.sh",
    "build/asan-sweep.sh": "/tmp/irctui-menu/g4/asan_sweep.sh",
    "build/build-caret.sh": "/tmp/irctui-caret/build.sh",
    "build/build-focus.sh": "/tmp/irctui-focus/build.sh",
    "build/dev-build-verctl.sh": "/tmp/verctl/dev_build.sh",
    "build/drive-poc.sh": "/tmp/em/drive_poc.sh",
    "build/run-focus.sh": "/tmp/irctui-focus/run.sh",
    "build/sweep-g5.sh": "/tmp/irctui-menu/g5/sweep.sh",
    "build/syntax-real-ncurses.sh": "/tmp/real_syntax.sh",
    "build/verify-g2.sh": "/tmp/irctui-menu/g2/verify.sh",
    "doc/doxygen-block-builder.py": "/tmp/g6_doc.py",
    "doc/mermaid-lint.py": "/tmp/mmlint.py",
    "pty/emulator-ech.py": "/tmp/irctui-caret/pty_screen.py",
    "pty/emulator-noech.py": "/tmp/irctui-caret/pty_screen_pre_ech.py",
    "pty/test_pty.py": "/tmp/irctui-menu/cur/test_pty.py",
    "pty/vt.py": "/tmp/vt.py",
    "pty/vt-wsd.py": "/tmp/irctui-wsd/vt.py",
    "pty/pty_focus.py": "/tmp/irctui-focus/pty_focus.py",
    "pty/pty_d2.py": "/tmp/irctui-wsd/pty_d2.py",
    "pty/pty_resize.py": "/tmp/irctui-wsd/pty_resize.py",
    "pty/pty_wsd.py": "/tmp/irctui-wsd/pty_wsd.py",
    "pty/diag-resize.py": "/tmp/irctui-wsd/diag_resize.py",
    "pty/diag-resize-2.py": "/tmp/irctui-wsd/diag2.py",
    "pty/diag-resize-3.py": "/tmp/irctui-wsd/diag3.py",
    "probe/ab/p_echo/g3_menu.py": "/tmp/irctui-ab/p_ech/g3_menu.py",
    "probe/ab/p_echo/stale_marker.py": "/tmp/irctui-ab/p_ech/stale_marker.py",
    "probe/ab/p_echo/staleprobe.py": "/tmp/irctui-ab/p_ech/staleprobe.py",
    "probe/ab/p_noecho/g3_menu.py": "/tmp/irctui-ab/p_noech/g3_menu.py",
    "probe/ab/p_noecho/stale_marker.py": "/tmp/irctui-ab/p_noech/stale_marker.py",
    "probe/ab/p_noecho/staleprobe.py": "/tmp/irctui-ab/p_noech/staleprobe.py",
}

# Directories copied without renaming, and the /tmp tree they came from.
DIR_ORIGIN = {
    "probe/menu": "/tmp/irctui-menu",
    "probe/caret": "/tmp/irctui-caret",
    "parity": "/tmp/parity",
    "source": "/tmp",
}

# Files in pty/ that came from the caret scratch tree.
CARET = {
    "arrow_probe.py", "clickdiag.py", "dump_screen.py", "esc_latency.py",
    "escdump.py", "mousebits.py", "peek.py", "popx.py", "timing.py", "ws.py",
}
ROOT = {"cap.py", "sweep.py", "click_demo.py", "drive_demo.py"}


def origin(rel):
    if rel in PROVENANCE:
        return PROVENANCE[rel]
    for prefix, src in DIR_ORIGIN.items():
        if rel.startswith(prefix + "/"):
            return src + "/" + rel[len(prefix) + 1:]
    if rel.startswith("pty/"):
        name = rel[4:]
        if name in CARET:
            return "/tmp/irctui-caret/" + name
        if name in ROOT:
            return "/tmp/" + name
    return "(not recorded)"


def purpose(path):
    """Each fixture's own leading comment or docstring, verbatim."""
    try:
        lines = path.read_text(errors="replace").splitlines()
    except OSError:
        return "(unreadable)"
    for raw in lines[:40]:
        s = raw.strip()
        if not s or s.startswith("#!"):
            continue
        if s.startswith("#"):
            t = s.lstrip("#").strip()
            if t and not t.startswith("---") and "coding" not in t:
                return t
            continue
        if s.startswith(('"""', "'''")):
            t = s.strip("\"'").strip()
            if t:
                return t
            continue
        return "`" + s[:60] + "`"
    return "(no leading description)"


def main():
    groups = {}
    for p in sorted(HERE.rglob("*")):
        if p.is_dir() or p.suffix not in (".py", ".sh"):
            continue
        rel = str(p.relative_to(HERE))
        if rel == "make-index.py":
            continue
        groups.setdefault(str(p.parent.relative_to(HERE)), []).append(p)

    out = []
    out.append("# Fixture index")
    out.append("")
    out.append("Generated by `make-index.py` — do not edit by hand. Every row's")
    out.append("purpose is the fixture's own leading comment or docstring, quoted")
    out.append("verbatim; `origin` is the scratch path it was retrieved from.")
    out.append("")
    out.append("These are archival copies. Most hardcode `/tmp/...` paths for the")
    out.append("build trees and binaries they were written against, so they will not")
    out.append("run unmodified from this directory — see §12 of")
    out.append("`../IRCITUILIB_TEST_STRATEGIES.md`.")
    out.append("")
    out.append(f"Total: {sum(len(v) for v in groups.values())} scripts.")
    out.append("")

    for d in sorted(groups):
        out.append(f"## `{d}/`")
        out.append("")
        out.append("| file | lines | purpose | origin |")
        out.append("|---|---|---|---|")
        for p in groups[d]:
            rel = str(p.relative_to(HERE))
            try:
                n = len(p.read_text(errors="replace").splitlines())
            except OSError:
                n = 0
            desc = purpose(p).replace("|", "\\|")
            out.append(f"| `{p.name}` | {n} | {desc} | `{origin(rel)}` |")
        out.append("")

    (HERE / "INDEX.md").write_text("\n".join(out))
    print(f"wrote {HERE / 'INDEX.md'}")


if __name__ == "__main__":
    sys.exit(main())
